import csv
import io
import re
from collections import Counter

def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str):
        raw_csv = str(raw_csv)

    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    try:
        csv.field_size_limit(100000000)
    except (OverflowError, ValueError):
        pass

    def read_records(text):
        stream = io.StringIO(text, newline="")
        try:
            return [list(row) for row in csv.reader(
                stream,
                delimiter=",",
                quotechar='"',
                doublequote=True,
                skipinitialspace=False,
                strict=False
            )]
        except csv.Error:
            rows = []
            row = []
            field = []
            quoted = False
            at_field_start = True
            i = 0

            while i < len(text):
                ch = text[i]

                if quoted:
                    if ch == '"':
                        if i + 1 < len(text) and text[i + 1] == '"':
                            field.append('"')
                            i += 2
                            continue
                        quoted = False
                    else:
                        field.append(ch)
                    i += 1
                    continue

                if ch == '"' and at_field_start:
                    quoted = True
                    at_field_start = False
                    i += 1
                elif ch == ",":
                    row.append("".join(field))
                    field = []
                    at_field_start = True
                    i += 1
                elif ch == "\r" or ch == "\n":
                    row.append("".join(field))
                    rows.append(row)
                    row = []
                    field = []
                    at_field_start = True
                    if ch == "\r" and i + 1 < len(text) and text[i + 1] == "\n":
                        i += 2
                    else:
                        i += 1
                else:
                    field.append(ch)
                    at_field_start = False
                    i += 1

            if field or row or (text and text[-1:] == ","):
                row.append("".join(field))
                rows.append(row)

            return rows

    records = read_records(raw_csv)
    if not records:
        return {"columns": [], "rows": []}

    nonblank_indices = [
        i for i, row in enumerate(records)
        if any(value != "" for value in row)
    ]
    if not nonblank_indices:
        return {"columns": [], "rows": []}

    expected_width = 9
    widths = [len(records[i]) for i in nonblank_indices]
    width_counts = Counter(widths)

    if expected_width in width_counts:
        target_width = expected_width
    else:
        plausible = [(count, width) for width, count in width_counts.items() if width > 1]
        target_width = max(plausible)[1] if plausible else max(widths)

    number_re = re.compile(r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)%?$")
    currency_re = re.compile(r"^[^\w\s]?[+-]?\d[\d,]*(?:\.\d+)?$")
    date_re = re.compile(r"^\d{1,4}[-/.]\d{1,2}[-/.]\d{1,4}$")
    time_re = re.compile(r"^\d{1,2}:\d{2}(?::\d{2})?(?:\s*[AaPp][Mm])?$")
    identifier_re = re.compile(r"^[A-Za-z_][A-Za-z0-9_ .()/+-]*$")

    def typed_value(value):
        value = value.strip()
        if not value:
            return False
        lower = value.lower()
        return bool(
            number_re.match(value)
            or currency_re.match(value)
            or date_re.match(value)
            or time_re.match(value)
            or lower.startswith(("http://", "https://", "ftp://", "www."))
        )

    def header_score(index):
        row = records[index]
        score = 100.0 if len(row) == target_width else -100.0
        stripped = [value.strip() for value in row]

        score += sum(1.5 for value in stripped if value)
        score += sum(1.5 for value in stripped if identifier_re.match(value or ""))
        score -= sum(5.0 for value in stripped if typed_value(value))
        score += len(set(stripped)) * 0.25

        following = nonblank_indices[nonblank_indices.index(index) + 1:]
        for distance, next_index in enumerate(following[:10]):
            next_row = records[next_index]
            if len(next_row) == target_width:
                score += max(1.0, 5.0 - distance * 0.35)
            else:
                score -= 1.0

            if distance == 0:
                limit = min(len(row), len(next_row))
                for col in range(limit):
                    if (
                        stripped[col]
                        and identifier_re.match(stripped[col])
                        and typed_value(next_row[col])
                    ):
                        score += 2.0

        score -= index * 0.01
        return score

    candidates = [
        i for i in nonblank_indices
        if len(records[i]) == target_width
    ]
    if not candidates:
        candidates = nonblank_indices

    search_candidates = candidates[:200]
    header_index = max(search_candidates, key=header_score)
    columns = list(records[header_index])

    if len(columns) < target_width:
        columns.extend("" for _ in range(target_width - len(columns)))
    elif len(columns) > target_width:
        columns = columns[:target_width - 1] + [
            ",".join(columns[target_width - 1:])
        ]

    rows = []
    for row in records[header_index + 1:]:
        if not row or not any(value != "" for value in row):
            continue

        normalized = list(row)
        if len(normalized) < target_width:
            normalized.extend("" for _ in range(target_width - len(normalized)))
        elif len(normalized) > target_width:
            normalized = normalized[:target_width - 1] + [
                ",".join(normalized[target_width - 1:])
            ]

        rows.append(normalized)

    return {"columns": columns, "rows": rows}
